-- Synthetic PostgreSQL integration cases; no production execution.
CREATE TABLE qa_results(group_id text,result text,detail text); CREATE TABLE qa_frozen(snapshot jsonb);
CREATE FUNCTION qa_assert(test boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF test IS DISTINCT FROM true THEN RAISE EXCEPTION '%',message; END IF; END $$;
DO $case$ DECLARE v jsonb; BEGIN PERFORM qa_assert((SELECT count(*)=2 AND bool_and(pg_get_userbyid(proowner)='postgres' AND proacl='{postgres=X/postgres}'::aclitem[]) FROM pg_proc WHERE oid IN('combat_consumer_private.scene_snapshot_v2(uuid)'::regprocedure,'combat_consumer_private.narrative_tech_sources_v1(uuid)'::regprocedure)),'exact owner and ACL');
SELECT snapshot INTO v FROM qa_legacy;
UPDATE combat_consumer_private.activities SET policy_id='ordinary_unprotected';
